          "description": "INSERT_DESCRIPTION",
          "default": "INSERT_DEFAULT",
          "INSERT_BOUND_CONDITION(S)": INSERT_BOUND_VALUE(S)
        }
      },
      "required": ["INSERT_PARAMETER_1_NAME", "INSERT_PARAMETER_N_NAME"],
      "additionalProperties": false
    }
  },
  "properties": {
    "/**": {
      "type": "object",
      "properties": {
        "ros__parameters": {
          "$ref": "#/definitions/INSERT_ROS_NODE_NAME"
        }
      },
      "required": ["ros__parameters"],
      "additionalProperties": false
    }
  },
  "required": ["/**"],
  "additionalProperties": false
}
```

架构文件路径为 `INSERT_PATH_TO_PACKAGE/schema/` ,架构文件名为 `INSERT_NODE_NAME.schema.json` .要使模板适应 ROS 节点,请替换每个 `INSERT_...` 并添加所有参数 `1..N`.

使用完善的标准可以使用传统工具.以下是如何使用 VS Code 将架构链接到参数文件的示例.这使开发人员能够使用方便的功能,例如自动完成和参数绑定验证.

在托管项目的根目录中,创建一个包含两个文件的 `.vscode` 文件夹;`extensions.json` 包含

```
{
  "recommendations": ["redhat.vscode-yaml"]
}
```

以及 `settings.json` 包含

```
{
  "yaml.schemas": {
    "./INSERT_PATH_TO_PACKAGE/schema/INSERT_NODE_NAME.schema.json": "**/INSERT_NODE_NAME/config/*.param.yaml"
  }
}
```

RedHat YAML 扩展允许使用 JSON 架构验证 YAML 文件, `yaml.schemas` `设置将` *.schema.json `文件与` config/ `文件夹中的所有`*.param.yaml `文件相关联.

本节介绍了一种推荐的方法,即仅在需要时使用 `Subscription->take()` 方法获取消息. 下面给出的示例代码显示,在执行任何回调函数期间都会调用 `Subscription->take()` 方法.大多数情况下,在接收到的消息被主逻辑消费之前,会调用 Subscription->take()` 方法. 在这种情况下,将从订阅队列(嵌入在订阅对象中的队列)中检索主题消息,而不是使用回调函数.准确地说,您必须对代码进行编程,以便不会自动调用回调函数.

```
SteeringReport msg;
  rclcpp::MessageInfo msg_info;
  if (sub_->take(msg, msg_info)) {
    // processing and publishing after this
```

使用这种方式有以下好处.

- 可以减少对订阅回调函数的调用次数
- 无需从主逻辑不消耗的订阅中获取主题消息
- 回调函数没有强制线程唤醒,这会导致多线程编程、数据争用和独占锁定

为了防止回调函数被自动调用,回调函数必须属于一个回调组,该回调函数的回调函数未添加到任何执行程序中. 根据 `create_subscription`_](http://docs.ros.org/en/iron/p/rclcpp/generated/classrclcpp_1_1Node.html) 的 [_API 规范,即使回调函数没有作,也必须将回调函数注册到基于 `rclcpp::Subscription` 的对象. 以下是 [*ros2_subscription_examples/simple_examples/src/timer_listener.cpp*](https://github.com/takam5f2/ros2_subscription_examples/blob/main/simple_examples/src/timer_listener.cpp) 中的示例代码片段.

```
rclcpp::CallbackGroup::SharedPtr cb_group_not_executed = this->create_callback_group(
        rclcpp::CallbackGroupType::MutuallyExclusive, false);
    auto subscription_options = rclcpp::SubscriptionOptions();
    subscription_options.callback_group = cb_group_not_executed;

    rclcpp::QoS qos(rclcpp::KeepLast(10));
    if (use_transient_local) {
      qos = qos.transient_local();
    }

    sub_ = create_subscription<std_msgs::msg::String>("chatter", qos, not_executed_callback, subscription_options);
```

在上面的代码中, `cb_group_not_executed` 是通过使用第二个参数 `false` 调用 `create_callback_group` 创建的.属于回调组的任何回调函数都不会被 Executor 调用. 如果 subscription_options 的 callback_group 成员设置为 cb_group_not_executed,则在收到相应的主题消息 not_executed_callback 时,将不会调用 . `create_callback_group` 的第二个参数定义如下.

要从基于 `Subscription` 的对象中获取主题消息,请在预期时间调用 `take()` 方法. 以下是使用 `take()` 方法的 [*ros2_subscription_examples/simple_examples/src/timer_listener.cpp*](https://github.com/takam5f2/ros2_subscription_examples/blob/main/simple_examples/src/timer_listener.cpp) 的示例代码片段.

```
std_msgs::msg::String msg;
  rclcpp::MessageInfo msg_info;
  if (sub_->take(msg, msg_info)) {
    RCLCPP_INFO(this->get_logger(), "Catch message");
    RCLCPP_INFO(this->get_logger(), "I heard: [%s]", msg.data.c_str());
```

在上面的代码中,`take(msg, msg_info)` 由从 `rclcpp::Subscription` 类实例化的 `sub_` 对象调用.它在计时器驱动的回调函数中调用.`msg` 和 `msg_info` 分别表示消息正文及其元数据.如果在调用 `take(msg, msg_info)` 时订阅队列中有消息,则该消息将复制到 `msg`. 如果成功从订阅中获取消息,则 `take(msg, msg_info)` 返回 `true`.在这种情况下,上面的代码从 `RCLCPP_INFO` 打印出消息的字符串数据. 如果消息未从订阅中获取,则 `take(msg, msg_info)` 返回 `false`. 调用 `take(msg, msg_info)` 时,如果订阅队列的大小大于 1,并且队列中有两条或多条消息,则最早的消息将复制到 `msg`.如果队列的大小为 1,则始终获取最新消息.

注意

您可以使用 `take()` 方法的返回值检查是否存在传入消息.但是,您必须注意 take() 方法的破坏性.`take()` 方法修改订阅队列.此外,`take()` 方法是不可逆的,并且没有针对 `take()` 方法的撤消作.仅使用 `take()` 方法检查传入消息总是会更改订阅队列.如果您想在不更改订阅队列的情况下进行检查,建议使用 rclcpp::WaitSet.有关详细信息,请参阅 [*[supplement] Use rclcpp::WaitSet*](supp-wait_set/).

注意

ROS 2 提供了 Serialized Message 功能,它支持与 [*Class SerializedMessage*](http://docs.ros.org/en/humble/p/rclcpp/generated/classrclcpp_1_1SerializedMessage.html) 中描述的任意消息类型的通信.它由 Autoware 中的 `topic_state_monitor` 使用. 您必须使用 `take_serialized()` 方法而不是 `take()` 方法,才能从订阅中获取基于 `rclcpp::SerializedMessage` 的消息.

以下是 [*ros2_subscription_examples/simple_examples/src/timer_listener_serialized_message.cpp*](https://github.com/takam5f2/ros2_subscription_examples/blob/main/simple_examples/src/timer_listener_serialized_message.cpp) 中的示例代码片段.

```
// receive the serialized message.
      rclcpp::MessageInfo msg_info;
      auto msg = sub_->create_serialized_message();

      if (sub_->take_serialized(*msg, msg_info) == false) {
        return;
      }
```

在上面的代码中,`msg` 由 `create_serialized_message()` 创建,用于存储接收到的消息,其类型为 `std::shared_ptr<::rclcpp::SerializedMessage>` .您可以使用 `take_serialized()` 方法获取 `rclcpp::SerializedMessage` 类型的消息.请注意,`take_serialized()` 方法需要引用类型 data 作为其第一个参数.由于 `msg` 是一个指针,因此 `*msg` 应该作为第一个参数传递给 `take_serialized().

注意

如果使用 QoS 设置配置了多个队列大小,则订阅对象可以在其队列中保存多条消息.使用 callback function 的常规方式强制每条消息执行一个 callback function.换句话说,存在一个约束;回调函数的单个周期处理一条消息.请注意,使用传统方式时,如果订阅队列中有一条或多条消息,则采用最早的消息,并分配一个线程来执行回调函数,该函数一直持续到队列为空. `take()` 方法将缓解此限制.`take()` 方法可以多次迭代调用,因此回调函数的单个循环可以处理 `take()` 方法获取的多个消息.

下面是一个示例代码,摘自 [*ros2_subscription_examples/simple_examples/src/timer_batch_listener.cpp*](https://github.com/takam5f2/ros2_subscription_examples/blob/main/simple_examples/src/timer_batch_listener.cpp),它在回调函数的单个循环中调用 `take()` 方法.

```
std_msgs::msg::String msg;
      rclcpp::MessageInfo msg_info;
      while (sub_->take(msg, msg_info))
      {
        RCLCPP_INFO(this->get_logger(), "Catch message");
        RCLCPP_INFO(this->get_logger(), "I heard: [%s]", msg.data.c_str());
```

在上面的代码中,`while(sub->take(msg, msg_info))` 继续从订阅队列中获取消息,直到队列为空.获取的每条消息都按迭代进行处理. 请注意,您必须通过考虑回调函数的频率和消息接收的频率来确定订阅队列的大小.例如,以 10Hz 的频率调用回调函数,以 50Hz 的频率接收 Topic 消息,则订阅队列的大小必须至少为 5,以免丢失收到的消息.

分配线程来执行每条消息的回调函数将导致性能开销.您可以使用本节中介绍的方式来避免意外开销. 当接收频率和消费频率之间存在较大差异时,这种方式将有效.例如,即使以高于 100 Hz 的频率接收到 CAN 报文,用户逻辑也会以较慢的频率(如 10 Hz)使用报文.在这种情况下,用户逻辑应该使用 `take()` 方法检索所需数量的消息,以避免意外的开销.

您可以结合使用 `take()` (严格来说是 `take_type_erased()`) 方法和回调函数,以一致的方式处理收到的消息.使用此组合不需要唤醒线程. 以下是 [*ros2_subscription_examples/simple_examples/src/timer_listener_using_callback.cpp*](https://github.com/takam5f2/ros2_subscription_examples/blob/main/simple_examples/src/timer_listener_using_callback.cpp) 中的示例代码片段.

```
auto msg = sub_->create_message();
      rclcpp::MessageInfo msg_info;
      if (sub_->take_type_erased(msg.get(), msg_info)) {
        sub_->handle_message(msg, msg_info);
```

在上面的代码中,在通过 `handle_message()` 方法调用已注册的回调函数之前,`take_type_erased()` 方法会获取一条消息.请注意,您必须使用 `take_type_erased()` 而不是 `take()` .`take_type_erased()` 需要 `void` 类型的数据作为其第一个参数.你必须使用 `get()` 方法将类型为 `shared_ptr` 的 `msg` 转换为 `void` 类型.然后,使用获取的消息调用 `handle_message()` 方法.在 `handle_message()` 中调用已注册的回调函数. 你不需要处理传递给 `take_type_erased()` 和 `handle_message()` 的消息类型.您可以将 message 变量定义为 `auto msg = sub_->create_message();`. 你也可以参考 [*the API document*](http://docs.ros.org/en/humble/p/rclcpp/generated/classrclcpp_1_1SubscriptionBase.html#_CPPv4N6rclcpp16SubscriptionBase16take_type_erasedEPvRN6rclcpp11MessageInfoE) 来了解`create_message()`、`take_type_erased()` 和 `handle_message()`.

要通过进程内通信处理消息,请调用 `take_data()` 方法,然后调用 `execute()` 方法,如下所示.

```
// Execute any entities of the Waitable that may be ready
std::shared_ptr<void> data = waitable.take_data();
waitable.execute(data);
```

这是 [*ros2_subscription_examples/intra_process_talker_listener/src/timer_listener_intra_process.cpp 在 main · takam5f2/ros2_subscription_examples*](https://github.com/takam5f2/ros2_subscription_examples/blob/main/intra_process_talker_listener/src/timer_listener_intra_process.cpp) 中的示例程序. 您可以按如下方式运行该程序.如果将 `true` 设置为 `use_intra_process_comms` ,则执行进程内通信,而如果设置为 `false`,则执行进程间通信.

```
ros2 intra_process_talker_listener talker_listener_intra_process.launch.py use_intra_process_comms:=true
```

这是 main · takam5f2/ros2_subscription_examples_](https://github.com/takam5f2/ros2_subscription_examples/blob/main/intra_process_talker_listener/src/timer_listener_intra_process.cpp) 的 [_ros2_subscription_examples/intra_process_talker_listener/src/timer_listener_intra_process.cpp 的片段.

```
// check if intra-process communication is enabled.
      if (this->get_node_options().use_intra_process_comms()){

        // get the intra-process subscription`s waitable.
        auto intra_process_sub = sub_->get_intra_process_waitable();

// check if the waitable has data.
        if (intra_process_sub->is_ready(nullptr) == true) {

          // take the data and execute the callback.
          std::shared_ptr<void> data = intra_process_sub->take_data();

          RCLCPP_INFO(this->get_logger(), " Intra-process communication is performed.");

          // execute the callback.
          intra_process_sub->execute(data);
```

以下是上述代码的逐行解释.

- `if (this->get_node_options().use_intra_process_comms()){`
- 该语句使用 `NodeOptions` 检查是否启用了进程内通信

- `auto intra_process_sub = sub_->get_intra_process_waitable();`
- 该语句表示获取执行进程内通信的体现对象

- `if (intra_process_sub->is_ready(nullptr) == true) {`
- 该语句检查是否已通过进程内通信收到消息
- `is_ready()` 的参数是 `rcl_wait_set_t` 类型,但由于该参数未在 `is_ready()` 中使用,因此暂时使用 `nullptr` .
- 使用 `nullptr` 目前是一种解决方法,因为它没有意图.

- `std::shared_ptr<void> data = intra_process_sub->take_data();`
- 该语句表示从 Subscription 获取主题消息,用于进程内通信.
- `intra_process_sub->take_data()` 不返回指示消息是否被成功接收的布尔值,因此需要事先调用 `is_ready()` 来检查这一点

- `intra_process_sub->execute(data);`
- 在 `execute()` 中调用与收到的消息对应的回调函数
- 回调函数由调用 `execute()` 的线程执行,没有上下文切换

如 [*call Subscription object*] 的 take() 方法中所述(./index.md#call-take-method-of-subscription-object),`take()` 方法是不可逆的.一旦执行了 `take()` 方法,订阅对象的状态就会发生变化.因为没有针对 `take()` 方法的撤消作,所以订阅对象无法恢复到之前的状态.你可以在调用 `take()` 之前使用 `rclcpp::WaitSet` 来检查订阅队列中传入消息的到达情况. 以下示例代码显示了 `wait_set_.wait()` 如何告诉你已经收到了一条消息,并且可以通过 `take()` 获取.

```
auto wait_result = wait_set_.wait(std::chrono::milliseconds(0));
      if (wait_result.kind() == rclcpp::WaitResultKind::Ready &&
          wait_result.get_wait_set().get_rcl_wait_set().subscriptions[0]) {
            sub_->take(msg, msg_info);
            RCLCPP_INFO(this->get_logger(), "Catch message");
            RCLCPP_INFO(this->get_logger(), "I heard: [%s]", msg.data.c_str());
```

单个 `rclcpp::WaitSet` 对象能够观察多个订阅对象.如果不同主题有多个订阅,您可以检查每个订阅的传入消息的到达情况.自主机器人领域使用的算法需要多个传入消息,例如传感器数据或驱动状态.对多个订阅使用 `rclcpp::WaitSet` ,他们能够在不接收任何消息的情况下检查所需的消息是否已到达.

```
auto wait_result = wait_set_.wait(std::chrono::milliseconds(0));
      bool received_all_messages = false;
      if (wait_result.kind() == rclcpp::WaitResultKind::Ready) {
        for (auto wait_set_subs : wait_result.get_wait_set().get_rcl_wait_set().subscriptions) {
          if (!wait_set_subs) {
            RCLCPP_INFO_THROTTLE(get_logger(), clock, 5000, "Waiting for data...");
            return {};
          }
        }
        received_all_mesages = true;
      }
```

在上面的代码中,除非使用 `rclcpp::WaitSet`,否则如果不更改订阅对象的状态,就不可能验证所有需要的消息的到达.

您需要为基于 `rclcpp::WaitSet` 的对象注册一个触发器. 以下是 main · takam5f2/ros2_subscription_examples_](https://github.com/takam5f2/ros2_subscription_examples/blob/main/waitset_examples/src/timer_listener_triple_async.cpp) 的 [_ros2_subscription_examples/waitset_examples/src/timer_listener_triple_async.cpp 的片段

```
subscriptions_array_[0] = create_subscription<std_msgs::msg::String>("chatter", qos, not_executed_callback, subscription_options);
    subscriptions_array_[1] = create_subscription<std_msgs::msg::String>("slower_chatter", qos, not_executed_callback, subscription_options);
    subscriptions_array_[2] = create_subscription<std_msgs::msg::String>("slowest_chatter", qos, not_executed_callback, subscription_options);

    // Add subscription to waitset
    for (auto & subscription : subscriptions_array_) {
      wait_set_.add_subscription(subscription);
    }
```

在上面的代码中,`add_subscription()` 方法将创建的订阅注册到 `wait_set_` 对象. 基于 `rclcpp::WaitSet` 的对象基本上处理对象,每个对象都有相应的回调函数.基于 `rclcpp::WaitSet` 的对象不仅可以观察基于 `Subscription` 的对象,还可以观察基于 `Timer`、`Service` 或 `Action` 的对象.单个 `rclcpp::WaitSet` 对象接受不同类型对象的混合. 可在此处找到用于注册计时器触发器的示例代码.

```
wait_set_.add_timer(much_slower_timer_);
```

从 `rclcpp::WaitSet` 返回的测试结果的数据结构是嵌套的. 您可以通过以下 2 个步骤找到 `WaitSet` 结果;

1. 验证是否已调用任何触发器
2. 验证是否已触发指定的触发器

对于第 1 步,以下是从 main · takam5f2/ros2_subscription_examples_](https://github.com/takam5f2/ros2_subscription_examples/blob/main/waitset_examples/src/timer_listener_triple_async.cpp) 的 [_ros2_subscription_examples/waitset_examples/src/timer_listener_triple_async.cpp 获取的示例代码.

```
auto wait_result = wait_set_.wait(std::chrono::milliseconds(0));
      if (wait_result.kind() == rclcpp::WaitResultKind::Ready) {
        RCLCPP_INFO(this->get_logger(), "wait_set tells that some subscription is ready");
      } else {
        RCLCPP_INFO(this->get_logger(), "wait_set tells that any subscription is not ready and return");
        return;
      }
```

在上面的代码中,`auto wait_result = wait_set_.wait(std::chrono::milliseconds(0))` 测试 `wait_set_` 中的触发器是否已被调用.`wait()`方法的参数是超时持续时间.如果大于 0 毫秒或秒,该方法将等待收到消息,直到超时过期. If`wait_result.kind() == rclcpp::WaitResultKind::Ready`is`true`,则表示已调用任何触发器.

对于第 2 步,以下是从 main · takam5f2/ros2_subscription_examples_](https://github.com/takam5f2/ros2_subscription_examples/blob/main/waitset_examples/src/timer_listener_triple_async.cpp) 的 [_ros2_subscription_examples/waitset_examples/src/timer_listener_triple_async.cpp 获取的示例代码.

```
